param([ValidateSet('release','debug','asan')][string]$Mode,[ValidatePattern('^main[0-9]{2}$')][string]$BuildAttempt,[ValidatePattern('^[a-z0-9-]{1,90}$')][string]$Stage,[string[]]$Targets)
$ErrorActionPreference='Stop'
$repo=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$root=[IO.Path]::GetFullPath((Join-Path $repo ('out/prelive-pre-emulator-'+$Mode+'-'+$BuildAttempt)))
$stageRoot=Join-Path $repo ('out/windows-handoff/'+$Stage);$statePath=Join-Path $stageRoot 'state.json';$receiptPath=Join-Path $stageRoot ($Stage+'-verification.json')
$state=Get-Content -LiteralPath $statePath -Raw|ConvertFrom-Json;$receipt=Get-Content -LiteralPath $receiptPath -Raw|ConvertFrom-Json;$result=Get-Content -LiteralPath (Join-Path $stageRoot ($Stage+'-result.json')) -Raw|ConvertFrom-Json
if($state.status -cne 'COMPLETE' -or $receipt.native_exit -ne 0 -or $receipt.runner_exit -ne 0 -or $receipt.verification_exit -ne 0 -or -not $receipt.producer_complete -or $result.facts.active_final -ne 0 -or -not $result.facts.held_all_signaled -or -not $result.facts.streams_completed){throw 'completed native target required'}
$items=@(Get-ChildItem -LiteralPath $root -File -Recurse|Where-Object {$_.Extension -in @('.ilk','.map') -and [IO.Path]::GetFileNameWithoutExtension($_.Name) -cin $Targets});if(-not $items.Count){return}
$dest=Join-Path $repo ('out/retained/consolidation-20261008/'+$BuildAttempt+'-linker-cache-archives');[IO.Directory]::CreateDirectory($dest)|Out-Null
$archive=Join-Path $dest ($Stage+'.zip');$proof=$archive+'.verified.json';if((Test-Path -LiteralPath $archive) -or (Test-Path -LiteralPath $proof)){throw 'fresh archive required'}
$files=@($items|ForEach-Object {$p=[IO.Path]::GetFullPath($_.FullName);if(-not $p.StartsWith($root+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase) -or $_.Attributes -band [IO.FileAttributes]::ReparsePoint){throw 'literal target cache scope'};@{path=$p;relative=[IO.Path]::GetRelativePath($root,$p).Replace('\','/');bytes=$_.Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}})
Add-Type -AssemblyName System.IO.Compression
$s=[IO.File]::Open($archive,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write);$z=[IO.Compression.ZipArchive]::new($s,[IO.Compression.ZipArchiveMode]::Create,$false)
try{foreach($f in $files){$e=$z.CreateEntry($f.relative,[IO.Compression.CompressionLevel]::Optimal);$i=[IO.File]::OpenRead($f.path);$o=$e.Open();try{$i.CopyTo($o)}finally{$o.Dispose();$i.Dispose()}}}finally{$z.Dispose();$s.Dispose()}
$z=[IO.Compression.ZipFile]::OpenRead($archive);try{if($z.Entries.Count -ne $files.Count){throw 'archive set'};foreach($f in $files){$e=$z.GetEntry($f.relative);if($null -eq $e -or $e.Length -ne $f.bytes){throw 'archive bytes'};$s=$e.Open();$h=[Security.Cryptography.SHA256]::Create();try{$sha=[Convert]::ToHexString($h.ComputeHash($s)).ToLowerInvariant()}finally{$h.Dispose();$s.Dispose()};if($sha -cne $f.sha256 -or (Get-Item -LiteralPath $f.path).Length -ne $f.bytes -or (Get-FileHash -LiteralPath $f.path -Algorithm SHA256).Hash.ToLowerInvariant() -cne $f.sha256){throw 'archive/original SHA'}}}finally{$z.Dispose()}
$v=@{schema='pas.linker-cache-archive.v1';source_commit=(& git -C $repo rev-parse HEAD);root=$root;scope='completed native target MSVC incremental .ilk and linker .map only; executable, PDB, object, library and raw evidence retained';files=$files;stage=$Stage;receipt=@{path=$receiptPath;sha256=(Get-FileHash -LiteralPath $receiptPath -Algorithm SHA256).Hash.ToLowerInvariant()};archive=@{path=$archive;bytes=(Get-Item -LiteralPath $archive).Length;sha256=(Get-FileHash -LiteralPath $archive -Algorithm SHA256).Hash.ToLowerInvariant()};decoded_bytes=[long](($files|Measure-Object bytes -Sum).Sum);readback_verified=$true;device_operations=0;live_ready=$false}
[IO.File]::WriteAllText($proof,($v|ConvertTo-Json -Depth 20),[Text.UTF8Encoding]::new($false))
foreach($f in $files){$p=[IO.Path]::GetFullPath($f.path);if(-not $p.StartsWith($root+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase) -or [IO.Path]::GetExtension($p) -notin @('.ilk','.map')){throw 'checked literal deletion scope'};Remove-Item -LiteralPath $p -Force}
Write-Output ($Stage+' linker caches archived/readback verified: '+$files.Count+' files, '+$v.decoded_bytes+' bytes')